<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Lease; use App\Models\PropertySpace; use App\Models\Tenant; use App\Services\AuditService; use App\Services\LeaseActivationService; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class LeaseController extends Controller {
 public function index(Request $r):JsonResponse{$q=Lease::query()->where('organization_id',$r->attributes->get('organization_id'));foreach(['tenantId'=>'tenant_id','status'=>'status'] as $key=>$field)if($r->filled($key))$q->where($field,$r->input($key));return $this->success(['items'=>$q->latest()->get()->map(fn($lease)=>$this->data($lease))]);}
 public function show(Request $r,string $id):JsonResponse{$lease=Lease::where('organization_id',$r->attributes->get('organization_id'))->findOrFail($id);$data=$this->data($lease);$data['spaces']=DB::table('lease_spaces as lease_space')->join('property_spaces as space','space.id','=','lease_space.property_space_id')->join('properties as property','property.id','=','space.property_id')->where('lease_space.lease_id',$lease->id)->select('space.id','space.name as space_name','property.id as property_id','property.name as property_name','lease_space.start_date','lease_space.end_date')->get()->map(fn($space)=>['spaceId'=>$space->id,'spaceName'=>$space->space_name,'propertyId'=>$space->property_id,'propertyName'=>$space->property_name,'startDate'=>$space->start_date,'endDate'=>$space->end_date]);$data['installments']=DB::table('lease_installments')->where('lease_id',$lease->id)->orderBy('sequence_no')->get()->map(fn($installment)=>['id'=>$installment->id,'sequenceNo'=>$installment->sequence_no,'dueDate'=>$installment->due_date,'amount'=>(float)$installment->original_amount,'notes'=>$installment->notes]);return $this->success($data);}
 public function update(Request $r,string $id):JsonResponse{$d=$r->validate(['version'=>['required','integer','min:1'],'internalNumber'=>['required','string','max:80'],'tenantId'=>['required','uuid'],'startDate'=>['required','date'],'endDate'=>['required','date','after:startDate'],'annualRent'=>['required','numeric','gt:0'],'totalValue'=>['required','numeric','gt:0'],'currency'=>['sometimes','string','size:3'],'frequency'=>['required','in:annual,semi_annual,quarterly,monthly,one_time,custom'],'spaces'=>['required','array','min:1'],'spaces.*.spaceId'=>['required','uuid','distinct'],'spaces.*.startDate'=>['required','date'],'spaces.*.endDate'=>['required','date','after:spaces.*.startDate'],'installments'=>['required','array','min:1'],'installments.*.dueDate'=>['required','date'],'installments.*.amount'=>['required','numeric','gt:0']]);$org=$r->attributes->get('organization_id');$lease=DB::transaction(function()use($r,$id,$d,$org){$lease=Lease::where('organization_id',$org)->lockForUpdate()->findOrFail($id);if($lease->status!=='draft')abort(409,'لا يمكن تعديل عقد إيجار مفعّل أو منتهٍ.');if((int)$lease->version!==(int)$d['version'])abort(409,'تم تعديل العقد من مستخدم آخر؛ حدّث الصفحة ثم أعد المحاولة.');Tenant::query()->where('organization_id',$org)->where('status','active')->lockForUpdate()->findOrFail($d['tenantId']);if(round((float)collect($d['installments'])->sum('amount'),2)!==round((float)$d['totalValue'],2))abort(422,'مجموع الأقساط لا يطابق قيمة العقد.');$before=$this->data($lease);foreach($d['spaces'] as $space)PropertySpace::query()->where('organization_id',$org)->lockForUpdate()->findOrFail($space['spaceId']);DB::table('lease_spaces')->where('lease_id',$lease->id)->delete();DB::table('lease_installments')->where('lease_id',$lease->id)->delete();$lease->update(['tenant_id'=>$d['tenantId'],'internal_number'=>$d['internalNumber'],'start_date'=>$d['startDate'],'end_date'=>$d['endDate'],'annual_rent'=>$d['annualRent'],'total_value'=>$d['totalValue'],'currency'=>$d['currency']??'SAR','frequency'=>$d['frequency'],'version'=>$lease->version+1]);foreach($d['spaces'] as $space)DB::table('lease_spaces')->insert(['lease_id'=>$lease->id,'property_space_id'=>$space['spaceId'],'start_date'=>$space['startDate'],'end_date'=>$space['endDate']]);foreach($d['installments'] as $index=>$item)DB::table('lease_installments')->insert(['id'=>(string)Str::uuid(),'lease_id'=>$lease->id,'sequence_no'=>$index+1,'due_date'=>$item['dueDate'],'original_amount'=>$item['amount']]);$lease=$lease->fresh();AuditService::record($org,$r->user()->id,'lease.updated','lease',$lease->id,$before,$this->data($lease));return $lease;});return $this->success($this->data($lease));}
 public function store(Request $r):JsonResponse{$d=$r->validate(['internalNumber'=>['required','string','max:80'],'tenantId'=>['required','uuid'],'startDate'=>['required','date'],'endDate'=>['required','date','after:startDate'],'annualRent'=>['required','numeric','gt:0'],'totalValue'=>['required','numeric','gt:0'],'currency'=>['sometimes','string','size:3'],'frequency'=>['required','in:annual,semi_annual,quarterly,monthly,one_time,custom'],'spaces'=>['required','array','min:1'],'spaces.*.spaceId'=>['required','uuid','distinct'],'spaces.*.startDate'=>['required','date'],'spaces.*.endDate'=>['required','date','after:spaces.*.startDate'],'installments'=>['required','array','min:1'],'installments.*.dueDate'=>['required','date'],'installments.*.amount'=>['required','numeric','gt:0']]);$org=$r->attributes->get('organization_id');$lease=DB::transaction(function()use($d,$org){Tenant::query()->where('organization_id',$org)->where('status','active')->lockForUpdate()->findOrFail($d['tenantId']);if(round((float)collect($d['installments'])->sum('amount'),2)!==round((float)$d['totalValue'],2))abort(422,'مجموع الأقساط لا يطابق قيمة العقد.');$lease=Lease::create(['id'=>(string)Str::uuid(),'organization_id'=>$org,'tenant_id'=>$d['tenantId'],'internal_number'=>$d['internalNumber'],'start_date'=>$d['startDate'],'end_date'=>$d['endDate'],'annual_rent'=>$d['annualRent'],'total_value'=>$d['totalValue'],'currency'=>$d['currency']??'SAR','frequency'=>$d['frequency']]);foreach($d['spaces'] as $space){PropertySpace::query()->where('organization_id',$org)->lockForUpdate()->findOrFail($space['spaceId']);DB::table('lease_spaces')->insert(['lease_id'=>$lease->id,'property_space_id'=>$space['spaceId'],'start_date'=>$space['startDate'],'end_date'=>$space['endDate']]);}foreach($d['installments'] as $index=>$item)DB::table('lease_installments')->insert(['id'=>(string)Str::uuid(),'lease_id'=>$lease->id,'sequence_no'=>$index+1,'due_date'=>$item['dueDate'],'original_amount'=>$item['amount']]);return $lease;});AuditService::record($org,$r->user()->id,'lease.created','lease',$lease->id,null,$this->data($lease));return $this->success($this->data($lease),[],201);}
 public function activate(Request $request,string $leaseId,LeaseActivationService $service):JsonResponse{$lease=Lease::query()->where('organization_id',$request->attributes->get('organization_id'))->findOrFail($leaseId);$lease=$service->activate($lease,$request->user()->id);return $this->success($this->data($lease));}
 private function data(Lease $lease):array{return ['id'=>$lease->id,'internalNumber'=>$lease->internal_number,'tenantId'=>$lease->tenant_id,'startDate'=>$lease->start_date,'endDate'=>$lease->end_date,'annualRent'=>$lease->annual_rent,'totalValue'=>$lease->total_value,'currency'=>$lease->currency,'frequency'=>$lease->frequency,'status'=>$lease->status,'version'=>$lease->version];}
}
